-- oxy:deploy-phase=pre
--
-- #122: live supplier stock, shipping, quote and reservation preflight. EIGHT
-- new tables and NOTHING else — no column is added to, dropped from or narrowed
-- on any existing table, so this migration is correct against BOTH the image
-- still serving (which never writes any of these rows) and the one arriving.
--
-- The hand-written block at the END of this file is not generated by
-- drizzle-kit and MUST be re-applied after any regeneration. It carries five
-- enforcement functions, and each holds a rule the CHECK constraints above
-- cannot express because it is about a TRANSITION rather than a row:
--
--   * `mercaria_supplier_sourcing_policy_immutable` — a published policy
--     version freezes; publishing a new version is how the policy changes
--     (the `fee_schedules` / `retail_pricing_policies` mechanism).
--   * `mercaria_supplier_quote_immutable` — a quote's identity, request and
--     ANSWER columns never change, and its usage timestamps each move NULL → a
--     value exactly once. A quote is a record of what a supplier said; an
--     editable one could authorize a sale the supplier never agreed to.
--   * `mercaria_supplier_reservation_immutable` — the same, plus the two
--     one-way usage transitions and the bounded release-retry counters. What it
--     refuses above all is a change to `provider_reservation_id`,
--     `provider_expires_at` or `declared_capabilities`: those three are what
--     make a reservation row evidence of a SUPPLIER's commitment rather than a
--     local claim.
--   * `mercaria_supplier_quote_shipping_option_append_only` and
--     `mercaria_supplier_sourcing_attempt_append_only` — UPDATE and DELETE
--     refused outright. The option set is part of the frozen answer, and an
--     attempt trail somebody can edit answers no question worth asking.
--
-- On a regeneration: `bun run db:generate` emits the CREATE TABLE statements
-- only; paste this header back at the top and the trigger block back at the
-- bottom, then grep for each of the five function names to confirm all five
-- survived, and confirm the file carries exactly ONE deploy-phase marker
-- line (the anchored form at the very top; grep with a leading `^`).

CREATE TABLE "supplier_call_leases" (
	"id" text PRIMARY KEY NOT NULL,
	"supplier_account_id" text NOT NULL,
	"slot" integer NOT NULL,
	"lease_owner" text,
	"lease_until" timestamp with time zone,
	"window_start" timestamp with time zone NOT NULL,
	"calls_in_window" integer DEFAULT 0 NOT NULL,
	"window_allowance" integer NOT NULL,
	"created_at" timestamp with time zone DEFAULT date_trunc('milliseconds', now()) NOT NULL,
	"updated_at" timestamp with time zone DEFAULT date_trunc('milliseconds', now()) NOT NULL,
	CONSTRAINT "supplier_call_leases_slot_check" CHECK ("supplier_call_leases"."slot" >= 0),
	CONSTRAINT "supplier_call_leases_lease_shape_check" CHECK (num_nonnulls("supplier_call_leases"."lease_owner", "supplier_call_leases"."lease_until") in (0, 2)),
	CONSTRAINT "supplier_call_leases_window_check" CHECK ("supplier_call_leases"."calls_in_window" >= 0 and "supplier_call_leases"."window_allowance" >= 1
          and "supplier_call_leases"."calls_in_window" <= "supplier_call_leases"."window_allowance")
);
