CREATE TABLE "supplier_preflight_health" (
	"id" text PRIMARY KEY NOT NULL,
	"supplier_account_id" text NOT NULL,
	"window_start" timestamp with time zone NOT NULL,
	"attempts" bigint DEFAULT 0 NOT NULL,
	"successes" bigint DEFAULT 0 NOT NULL,
	"failures" bigint DEFAULT 0 NOT NULL,
	"timeouts" bigint DEFAULT 0 NOT NULL,
	"rate_limited" bigint DEFAULT 0 NOT NULL,
	"latency_ms_total" bigint DEFAULT 0 NOT NULL,
	"latency_samples" bigint DEFAULT 0 NOT NULL,
	"consecutive_failures" integer DEFAULT 0 NOT NULL,
	"last_success_at" timestamp with time zone,
	"last_failure_at" timestamp with time zone,
	"last_failure_kind" text,
	"created_at" timestamp with time zone DEFAULT date_trunc('milliseconds', now()) NOT NULL,
	"updated_at" timestamp with time zone DEFAULT date_trunc('milliseconds', now()) NOT NULL,
	CONSTRAINT "supplier_preflight_health_last_failure_kind_check" CHECK ("supplier_preflight_health"."last_failure_kind" in ('timeout', 'rate_limited', 'provider_error', 'transport_error', 'contract_violation', 'authentication_failed', 'capability_missing')),
	CONSTRAINT "supplier_preflight_health_counters_total_check" CHECK ("supplier_preflight_health"."attempts" = "supplier_preflight_health"."successes" + "supplier_preflight_health"."failures"),
	CONSTRAINT "supplier_preflight_health_counters_bounds_check" CHECK ("supplier_preflight_health"."successes" >= 0 and "supplier_preflight_health"."failures" >= 0
          and "supplier_preflight_health"."timeouts" between 0 and "supplier_preflight_health"."failures"
          and "supplier_preflight_health"."rate_limited" between 0 and "supplier_preflight_health"."failures"
          and "supplier_preflight_health"."latency_ms_total" >= 0
          and "supplier_preflight_health"."latency_samples" between 0 and "supplier_preflight_health"."attempts"
          and "supplier_preflight_health"."consecutive_failures" >= 0),
	CONSTRAINT "supplier_preflight_health_failure_shape_check" CHECK (num_nonnulls("supplier_preflight_health"."last_failure_at", "supplier_preflight_health"."last_failure_kind") in (0, 2))
);
