CREATE TABLE "supplier_preflight_suppressions" (
	"id" text PRIMARY KEY NOT NULL,
	"scope" text NOT NULL,
	"supplier_id" text,
	"supplier_account_id" text,
	"market_country" text,
	"kind" text NOT NULL,
	"origin" text NOT NULL,
	"reason" text NOT NULL,
	"sourcing_policy_id" text,
	"raised_by_oxy_user_id" text,
	"effective_from" timestamp with time zone NOT NULL,
	"expires_at" timestamp with time zone,
	"lifted_at" timestamp with time zone,
	"lifted_by_oxy_user_id" text,
	"lift_reason" text,
	"created_at" timestamp with time zone DEFAULT date_trunc('milliseconds', now()) NOT NULL,
	"updated_at" timestamp with time zone DEFAULT date_trunc('milliseconds', now()) NOT NULL,
	"suppression_key" text GENERATED ALWAYS AS ("scope" || '|' || coalesce("supplier_id", '') || '|' ||
            coalesce("supplier_account_id", '') || '|' || coalesce("market_country", '') || '|' || "kind") STORED NOT NULL,
	CONSTRAINT "supplier_preflight_suppressions_scope_check" CHECK ("supplier_preflight_suppressions"."scope" in ('supplier', 'supplier_account', 'market', 'supplier_account_market')),
	CONSTRAINT "supplier_preflight_suppressions_kind_check" CHECK ("supplier_preflight_suppressions"."kind" in ('kill_switch', 'health_degraded', 'quota_exhausted', 'capability_unavailable')),
	CONSTRAINT "supplier_preflight_suppressions_origin_check" CHECK ("supplier_preflight_suppressions"."origin" in ('operator', 'automatic_health')),
	CONSTRAINT "supplier_preflight_suppressions_scope_shape_check" CHECK (case "supplier_preflight_suppressions"."scope"
            when 'supplier' then "supplier_preflight_suppressions"."supplier_id" is not null
                                 and "supplier_preflight_suppressions"."supplier_account_id" is null
                                 and "supplier_preflight_suppressions"."market_country" is null
            when 'supplier_account' then "supplier_preflight_suppressions"."supplier_account_id" is not null
                                 and "supplier_preflight_suppressions"."supplier_id" is null
                                 and "supplier_preflight_suppressions"."market_country" is null
            when 'market' then "supplier_preflight_suppressions"."market_country" is not null
                                 and "supplier_preflight_suppressions"."supplier_id" is null
                                 and "supplier_preflight_suppressions"."supplier_account_id" is null
            when 'supplier_account_market' then "supplier_preflight_suppressions"."supplier_account_id" is not null
                                 and "supplier_preflight_suppressions"."market_country" is not null
                                 and "supplier_preflight_suppressions"."supplier_id" is null
            else false
          end),
	CONSTRAINT "supplier_preflight_suppressions_market_shape_check" CHECK ("supplier_preflight_suppressions"."market_country" is null or "supplier_preflight_suppressions"."market_country" ~ '^[A-Z]{2}$'),
	CONSTRAINT "supplier_preflight_suppressions_reason_check" CHECK (length(btrim("supplier_preflight_suppressions"."reason")) between 1 and 2000),
	CONSTRAINT "supplier_preflight_suppressions_origin_shape_check" CHECK (case "supplier_preflight_suppressions"."origin"
            when 'automatic_health' then "supplier_preflight_suppressions"."kind" = 'health_degraded'
                                       and "supplier_preflight_suppressions"."raised_by_oxy_user_id" is null
                                       and "supplier_preflight_suppressions"."sourcing_policy_id" is not null
                                       and "supplier_preflight_suppressions"."expires_at" is not null
            else "supplier_preflight_suppressions"."raised_by_oxy_user_id" is not null
          end),
	CONSTRAINT "supplier_preflight_suppressions_window_check" CHECK ("supplier_preflight_suppressions"."expires_at" is null or "supplier_preflight_suppressions"."expires_at" > "supplier_preflight_suppressions"."effective_from"),
	CONSTRAINT "supplier_preflight_suppressions_lift_check" CHECK (num_nonnulls("supplier_preflight_suppressions"."lifted_at", "supplier_preflight_suppressions"."lift_reason") in (0, 2)
          and ("supplier_preflight_suppressions"."lifted_by_oxy_user_id" is null or "supplier_preflight_suppressions"."lifted_at" is not null)
          and ("supplier_preflight_suppressions"."lift_reason" is null
               or length(btrim("supplier_preflight_suppressions"."lift_reason")) <= 2000))
);
