	CONSTRAINT "supplier_quote_shipping_options_window_check" CHECK (num_nonnulls("supplier_quote_shipping_options"."delivery_days_min", "supplier_quote_shipping_options"."delivery_days_max") in (0, 2)
          and ("supplier_quote_shipping_options"."delivery_days_min" is null
