-- ── Hand-written enforcement (#122) ───────────────────────────────────────────
-- drizzle-kit does not model triggers. See the header of this file for what
-- each one holds and what to do after a regeneration.

CREATE OR REPLACE FUNCTION mercaria_supplier_sourcing_policy_immutable()
RETURNS trigger AS $$
BEGIN
  -- A DRAFT is editable; anything published is frozen. Status may still move
  -- (active → superseded → retired) or a version could never be replaced.
  IF OLD.status = 'draft' THEN
    RETURN NEW;
  END IF;
  IF NEW.policy_key IS DISTINCT FROM OLD.policy_key
     OR NEW.version IS DISTINCT FROM OLD.version
     OR NEW.effective_start IS DISTINCT FROM OLD.effective_start
     OR NEW.effective_end IS DISTINCT FROM OLD.effective_end
     OR NEW.ranking_criteria IS DISTINCT FROM OLD.ranking_criteria
     OR NEW.required_capabilities IS DISTINCT FROM OLD.required_capabilities
     OR NEW.max_sourcing_attempts IS DISTINCT FROM OLD.max_sourcing_attempts
     OR NEW.max_supplier_share_bps IS DISTINCT FROM OLD.max_supplier_share_bps
     OR NEW.quote_ttl_seconds IS DISTINCT FROM OLD.quote_ttl_seconds
     OR NEW.provider_timeout_ms IS DISTINCT FROM OLD.provider_timeout_ms
     OR NEW.max_provider_concurrency IS DISTINCT FROM OLD.max_provider_concurrency
     OR NEW.max_provider_calls_per_minute IS DISTINCT FROM OLD.max_provider_calls_per_minute
     OR NEW.health_window_minutes IS DISTINCT FROM OLD.health_window_minutes
     OR NEW.health_minimum_samples IS DISTINCT FROM OLD.health_minimum_samples
     OR NEW.health_max_failure_bps IS DISTINCT FROM OLD.health_max_failure_bps
     OR NEW.health_suppression_minutes IS DISTINCT FROM OLD.health_suppression_minutes
     OR NEW.created_by_oxy_user_id IS DISTINCT FROM OLD.created_by_oxy_user_id THEN
    RAISE EXCEPTION 'supplier_sourcing_policies is immutable once published: publish a new version'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;--> statement-breakpoint
CREATE TRIGGER mercaria_supplier_sourcing_policy_immutable
BEFORE UPDATE ON "supplier_sourcing_policies"
FOR EACH ROW EXECUTE FUNCTION mercaria_supplier_sourcing_policy_immutable();--> statement-breakpoint

CREATE OR REPLACE FUNCTION mercaria_supplier_quote_immutable()
RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'supplier_quotes cannot be deleted: a quote is the evidence a charge was made against'
      USING ERRCODE = 'restrict_violation';
  END IF;

  -- Identity, request and ANSWER never change. Listed explicitly rather than as
  -- "everything except the usage columns", so a column added later is frozen by
  -- DEFAULT only if somebody adds it here — which is the direction that fails
  -- safe for a record, and the direction a reviewer will notice.
  IF NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.request_fingerprint IS DISTINCT FROM OLD.request_fingerprint
     OR NEW.supplier_id IS DISTINCT FROM OLD.supplier_id
     OR NEW.supplier_account_id IS DISTINCT FROM OLD.supplier_account_id
     OR NEW.environment IS DISTINCT FROM OLD.environment
     OR NEW.provider IS DISTINCT FROM OLD.provider
     OR NEW.declared_capabilities IS DISTINCT FROM OLD.declared_capabilities
     OR NEW.procurement_offer_id IS DISTINCT FROM OLD.procurement_offer_id
     OR NEW.supplier_sku IS DISTINCT FROM OLD.supplier_sku
     OR NEW.quantity IS DISTINCT FROM OLD.quantity
     OR NEW.checkout_group_id IS DISTINCT FROM OLD.checkout_group_id
     OR NEW.requested_currency IS DISTINCT FROM OLD.requested_currency
     OR NEW.destination_country IS DISTINCT FROM OLD.destination_country
     OR NEW.destination_region IS DISTINCT FROM OLD.destination_region
     OR NEW.identity_confirmation IS DISTINCT FROM OLD.identity_confirmation
     OR NEW.availability IS DISTINCT FROM OLD.availability
     OR NEW.unit_cost_amount IS DISTINCT FROM OLD.unit_cost_amount
     OR NEW.shipping_cost_amount IS DISTINCT FROM OLD.shipping_cost_amount
     OR NEW.shipping_basis IS DISTINCT FROM OLD.shipping_basis
     OR NEW.selected_shipping_service_code IS DISTINCT FROM OLD.selected_shipping_service_code
     OR NEW.tax_amount IS DISTINCT FROM OLD.tax_amount
     OR NEW.duty_amount IS DISTINCT FROM OLD.duty_amount
     OR NEW.status IS DISTINCT FROM OLD.status
     OR NEW.block_reasons IS DISTINCT FROM OLD.block_reasons
     OR NEW.exception_kind IS DISTINCT FROM OLD.exception_kind
     OR NEW.quoted_at IS DISTINCT FROM OLD.quoted_at
     OR NEW.expires_at IS DISTINCT FROM OLD.expires_at THEN
    RAISE EXCEPTION 'supplier_quotes records what a supplier said and is immutable; re-quote instead'
      USING ERRCODE = 'restrict_violation';
  END IF;

  -- Usage is ONE-WAY. Each of these moves NULL → a value exactly once, which is
  -- what makes "a quote consumed by one checkout cannot be attached to another"
  -- (#122 concurrency 3) true of a service bug and of `psql` alike.
  IF OLD.consumed_at IS NOT NULL AND NEW.consumed_at IS DISTINCT FROM OLD.consumed_at THEN
    RAISE EXCEPTION 'supplier_quotes.consumed_at is set once and never re-pointed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.consumed_by_checkout_group_id IS NOT NULL
     AND NEW.consumed_by_checkout_group_id IS DISTINCT FROM OLD.consumed_by_checkout_group_id THEN
    RAISE EXCEPTION 'a supplier quote consumed by one checkout cannot be attached to another'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.released_at IS NOT NULL AND NEW.released_at IS DISTINCT FROM OLD.released_at THEN
    RAISE EXCEPTION 'supplier_quotes.released_at is set once'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.superseded_by_quote_id IS NOT NULL
     AND NEW.superseded_by_quote_id IS DISTINCT FROM OLD.superseded_by_quote_id THEN
    RAISE EXCEPTION 'supplier_quotes.superseded_by_quote_id is set once'
      USING ERRCODE = 'restrict_violation';
  END IF;
  -- `order_id` is the ONE correlation that may be filled in later (the retail
  -- order does not exist when the quote is taken — ADR 0004 D4 step 1), and it
  -- may be filled in only once.
  IF OLD.order_id IS NOT NULL AND NEW.order_id IS DISTINCT FROM OLD.order_id THEN
    RAISE EXCEPTION 'supplier_quotes.order_id is set once and never re-pointed'
      USING ERRCODE = 'restrict_violation';
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;--> statement-breakpoint
CREATE TRIGGER mercaria_supplier_quote_immutable
BEFORE UPDATE OR DELETE ON "supplier_quotes"
FOR EACH ROW EXECUTE FUNCTION mercaria_supplier_quote_immutable();--> statement-breakpoint

CREATE OR REPLACE FUNCTION mercaria_supplier_reservation_immutable()
RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'supplier_reservations cannot be deleted: a hold Mercaria took is a fact about a supplier''s stock'
      USING ERRCODE = 'restrict_violation';
  END IF;

  -- These three are what make the row EVIDENCE of a supplier's commitment
  -- rather than a local claim. Nothing may edit them, ever.
  IF NEW.provider_reservation_id IS DISTINCT FROM OLD.provider_reservation_id
     OR NEW.provider_expires_at IS DISTINCT FROM OLD.provider_expires_at
     OR NEW.declared_capabilities IS DISTINCT FROM OLD.declared_capabilities
     OR NEW.quote_id IS DISTINCT FROM OLD.quote_id
     OR NEW.supplier_id IS DISTINCT FROM OLD.supplier_id
     OR NEW.supplier_account_id IS DISTINCT FROM OLD.supplier_account_id
     OR NEW.supplier_sku IS DISTINCT FROM OLD.supplier_sku
     OR NEW.quantity IS DISTINCT FROM OLD.quantity
     OR NEW.reserved_at IS DISTINCT FROM OLD.reserved_at
     OR NEW.single_use IS DISTINCT FROM OLD.single_use THEN
    RAISE EXCEPTION 'supplier_reservations records a supplier''s own commitment and is immutable'
      USING ERRCODE = 'restrict_violation';
  END IF;

  IF OLD.consumed_at IS NOT NULL AND NEW.consumed_at IS DISTINCT FROM OLD.consumed_at THEN
    RAISE EXCEPTION 'a single-use supplier reservation cannot be consumed twice'
      USING ERRCODE = 'restrict_violation';
  END IF;
  IF OLD.released_at IS NOT NULL AND NEW.released_at IS DISTINCT FROM OLD.released_at THEN
    RAISE EXCEPTION 'supplier_reservations.released_at is set once'
      USING ERRCODE = 'restrict_violation';
  END IF;
  -- The retry counter only ever climbs: a reset would let a bounded retry run
  -- forever, which is the one thing the bound exists to prevent.
  IF NEW.release_attempts < OLD.release_attempts THEN
    RAISE EXCEPTION 'supplier_reservations.release_attempts cannot decrease'
      USING ERRCODE = 'restrict_violation';
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;--> statement-breakpoint
CREATE TRIGGER mercaria_supplier_reservation_immutable
BEFORE UPDATE OR DELETE ON "supplier_reservations"
FOR EACH ROW EXECUTE FUNCTION mercaria_supplier_reservation_immutable();--> statement-breakpoint

CREATE OR REPLACE FUNCTION mercaria_supplier_quote_shipping_option_append_only()
